import { useLocation, useSearchParams } from 'react-router-dom';

// Fields that should always remain as strings, even if they contain only numeric values
const STRING_FIELDS = ['tokenId', 'trnscAmt', 'trnscTypeCd', 'trnscId', 'aliasNm', 'mpmType'];

const convertValue = (key: string, value: string): string | number | boolean => {
  // Fields that should always remain strings
  if (STRING_FIELDS.includes(key)) {
    return value;
  }

  // Convert "true" and "false" strings to boolean
  if (value === 'true') return true;
  if (value === 'false') return false;

  // Convert numeric strings to numbers
  if (!isNaN(Number(value)) && value !== '') {
    return Number(value);
  }

  return value;
};

export const useGetRouterState = <T>() => {
  const location = useLocation();
  const [searchParams] = useSearchParams();
  let routerState = location?.state as T;

  if (!routerState) {
    // Convert search params to an object with properly typed values
    const paramsEntries = Array.from(searchParams.entries());
    const parsedParams = paramsEntries.reduce(
      (acc, [key, value]) => {
        acc[key] = convertValue(key, value);
        return acc;
      },
      {} as Record<string, any>,
    );

    routerState = parsedParams as unknown as T;
  }

  return { routerState };
};
